    /**
     * The builder of headers' name for the OpenFGA component.
     */
    public static class OpenFgaHeaderNameBuilder {
        /**
         * The internal instance of the builder used to access to all the
         * methods representing the name of headers.
         */
        public static final OpenFgaHeaderNameBuilder INSTANCE = new OpenFgaHeaderNameBuilder();

        /**
         * The allow/deny verdict of the authorization check. Always overwritten
         * by the component, so a value set by an inbound message never survives
         * into the route.
         * 
         * The option is a: {@code Boolean} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code OpenFgaAllowed}.
         */
        public String openFgaAllowed() {
            return "CamelOpenFgaAllowed";
        }
        /**
         * Why the exchange was denied, set only on a deny. denied when OpenFGA
         * evaluated the relationship and answered no; missing-user,
         * missing-object, missing-relation, wildcard-subject or
         * invalid-identifier when the exchange never reached OpenFGA because
         * what it carried could not be used as a subject or an object;
         * invalid-contextual-tuple when a configured contextual tuple did not
         * resolve, so the check would have asked a different question than the
         * endpoint was configured to ask.
         * 
         * The option is a: {@code String} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code OpenFgaDenyReason}.
         */
        public String openFgaDenyReason() {
            return "CamelOpenFgaDenyReason";
        }
        /**
         * Set to true only when the exchange proceeded because failOpen is
         * enabled and OpenFGA could not be asked - nothing authorized it.
         * Absent on every verdict OpenFGA actually gave, so a route or an audit
         * trail can tell the two apart rather than seeing the same
         * CamelOpenFgaAllowed=true for both.
         * 
         * The option is a: {@code Boolean} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code OpenFgaFailedOpen}.
         */
        public String openFgaFailedOpen() {
            return "CamelOpenFgaFailedOpen";
        }
        /**
         * The subject the check was made for, as resolved from the endpoint's
         * user expression. Set for observability; it is not read as an input.
         * 
         * The option is a: {@code String} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code OpenFgaUser}.
         */
        public String openFgaUser() {
            return "CamelOpenFgaUser";
        }
        /**
         * The object the check was made against, as resolved from the
         * endpoint's object expression. Set for observability; it is not read
         * as an input.
         * 
         * The option is a: {@code String} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code OpenFgaObject}.
         */
        public String openFgaObject() {
            return "CamelOpenFgaObject";
        }
        /**
         * The relation that was checked. Set for observability; it is not read
         * as an input and cannot be used to demand a weaker permission than the
         * endpoint configured.
         * 
         * The option is a: {@code String} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code OpenFgaRelation}.
         */
        public String openFgaRelation() {
            return "CamelOpenFgaRelation";
        }
        /**
         * The identifier of the OpenFGA store that was consulted, so an audit
         * trail records which relationship graph produced the verdict.
         * 
         * The option is a: {@code String} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code OpenFgaStoreId}.
         */
        public String openFgaStoreId() {
            return "CamelOpenFgaStoreId";
        }
        /**
         * The continuation token the page came back with. Feed it back through
         * the continuationToken option to read on. The two operations end
         * differently: readTuples returns no token on its last page, so the
         * header is absent once the read is done, whereas readChanges always
         * returns a token - an empty body is what says the log has been read up
         * to date, and that last token is what lets the next poll resume
         * instead of replaying the whole log.
         * 
         * The option is a: {@code String} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code OpenFgaContinuationToken}.
         */
        public String openFgaContinuationToken() {
            return "CamelOpenFgaContinuationToken";
        }
        /**
         * How many relationship tuples the writeTuples operation wrote.
         * 
         * The option is a: {@code Integer} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code OpenFgaWrittenTuples}.
         */
        public String openFgaWrittenTuples() {
            return "CamelOpenFgaWrittenTuples";
        }
        /**
         * How many relationship tuples the deleteTuples operation deleted.
         * 
         * The option is a: {@code Integer} type.
         * 
         * Group: producer
         * 
         * @return the name of the header {@code OpenFgaDeletedTuples}.
         */
        public String openFgaDeletedTuples() {
            return "CamelOpenFgaDeletedTuples";
        }
    }
